//! Local output jobs freeze exact inputs and generated bytes. Confirmation and
//! download never recompile, rerun a Query, or alter an author document.
use super::export_conversions::{generate, template_slots};
use super::*;
use base64::Engine as _;
use std::{collections::BTreeMap, time::Instant};
use weftext_export::ExportArtifact;

const MAX_BYTES: usize = 64 * 1024 * 1024;
const STORE_BYTES: usize = 256 * 1024 * 1024;
const TTL: Duration = Duration::from_secs(3600);

#[derive(Clone)]
pub(crate) struct FrozenQueryOutput {
    pub(crate) root: String,
    pub(crate) value: Value,
    pub(crate) columns: Vec<String>,
    pub(crate) schema: Value,
    pub(crate) embedded: Option<EmbeddedQueryBasis>,
    pub(crate) born: Instant,
}
#[derive(Clone, PartialEq)]
pub(crate) struct EmbeddedQueryBasis {
    pub(crate) session_id: String,
    pub(crate) source_hash: String,
    pub(crate) serial: u64,
    pub(crate) occurrence_id: String,
}
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct EmbeddedQuerySelection {
    pub(crate) occurrence_id: String,
    pub(crate) query_id: String,
}
struct Job {
    input: String,
    artifact: Option<ExportArtifact>,
    reply: Value,
    born: Instant,
    confirmed: bool,
}
struct GenerationGuard {
    state: Arc<Mutex<ExportStore>>,
    id: String,
}
impl Drop for GenerationGuard {
    fn drop(&mut self) {
        if let Ok(mut store) = self.state.lock()
            && let Some(job) = store.jobs.get_mut(&self.id)
            && job.reply["status"] == "pending"
        {
            job.reply = json!({"id":self.id,"requestId":self.id,"status":"failed","code":"generationInterrupted","message":"本次生成已中断，原输入未改写；请明确重新生成"});
            job.born = Instant::now();
        }
    }
}
#[derive(Default)]
pub(crate) struct ExportStore {
    queries: HashMap<String, FrozenQueryOutput>,
    jobs: HashMap<String, Job>,
    expired: std::collections::BTreeSet<String>,
}
impl ExportStore {
    fn prune(&mut self) {
        self.queries.retain(|_, q| q.born.elapsed() < TTL);
        self.jobs.retain(|id, j| {
            if j.born.elapsed() < TTL || j.reply["status"] == "pending" {
                return true;
            }
            self.expired.insert(id.clone());
            false
        });
    }
    fn size(&self) -> usize {
        self.jobs
            .values()
            .map(|j| {
                j.artifact.as_ref().map_or(0, |a| a.bytes.len())
                    + j.input.len()
                    + j.reply.to_string().len()
            })
            .sum::<usize>()
            + self
                .queries
                .values()
                .map(|q| q.value.to_string().len() + q.schema.to_string().len())
                .sum::<usize>()
    }
}
fn store(state: &AppState) -> Result<std::sync::MutexGuard<'_, ExportStore>, ApiError> {
    state
        .exports
        .lock()
        .map_err(|_| ApiError::internal("输出会话不可用"))
}
pub(crate) fn retain_query(
    state: &AppState,
    root: String,
    output: &mut Value,
    columns: Vec<String>,
    schema: Value,
) -> Result<(), ApiError> {
    let bytes = output.to_string().len() + schema.to_string().len();
    let mut store = store(state)?;
    store.prune();
    if store.queries.len() >= 32
        && let Some(oldest) = store
            .queries
            .iter()
            .min_by_key(|(_, q)| q.born)
            .map(|(id, _)| id.clone())
    {
        store.queries.remove(&oldest);
    }
    if bytes > MAX_BYTES || store.size() + bytes > STORE_BYTES {
        output["exportUnavailable"] =
            json!("当前冻结结果超过输出缓存预算；已显示结果不会被悄悄重新查询。");
        return Ok(());
    }
    let id = uuid::Uuid::new_v4().to_string();
    output["queryId"] = json!(id);
    store.queries.insert(
        id,
        FrozenQueryOutput {
            root,
            value: output.clone(),
            columns,
            schema,
            embedded: None,
            born: Instant::now(),
        },
    );
    Ok(())
}
pub(crate) fn bind_embedded_query(
    state: &AppState,
    id: &str,
    basis: EmbeddedQueryBasis,
) -> Result<(), ApiError> {
    let mut store = store(state)?;
    let query = store
        .queries
        .get_mut(id)
        .ok_or_else(|| ApiError::bad("冻结查询已过期，请明确重新运行"))?;
    if query.embedded.is_some() {
        return Err(ApiError::bad("冻结查询已绑定，不能重新关联正文位置"));
    }
    query.embedded = Some(basis);
    Ok(())
}
pub(crate) fn frozen_query(
    state: &AppState,
    id: &str,
    root: &str,
) -> Result<FrozenQueryOutput, ApiError> {
    let mut store = store(state)?;
    store.prune();
    let query = store.queries.get(id).ok_or_else(|| {
        ApiError::new(
            StatusCode::NOT_FOUND,
            "queryExpired",
            "原查询输出已过期；请明确重新查询并选择新结果",
        )
    })?;
    if std::path::Path::new(&query.root) != std::path::Path::new(root) {
        return Err(ApiError::bad("查询结果与当前笔记库不一致"));
    }
    Ok(query.clone())
}

pub(crate) fn router() -> Router<AppState> {
    Router::new()
        .route("/api/export/template", post(inspect_template))
        .route("/api/export/prepare", post(prepare))
        .route("/api/export/status", post(status))
        .route("/api/export/confirm", post(confirm))
        .route("/api/export/download", post(download))
        .route("/api/exchange/prepare", post(prepare_import))
        .route("/api/exchange/inspect", post(inspect_import))
        .route("/api/exchange/commit", post(commit_import))
}
